import { For, Show, createMemo, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { coverageNext, PROFILE_PATTERNS } from '../../model/parse.js';
import { activeDimensions } from '../list/pivot.jsx';
import { text } from '../../stores/view.js';
import { Chevron } from '../shared/chip.jsx';
import { TermHeader } from '../shared/header.jsx';
import { NodeChain, RowFold } from './form.jsx';
import { coversNode } from './form-model.js';
import { editLayerActive, Hook } from '../shared/edit-hook.jsx';
import { Field } from '../edit/hooks.jsx';
import { FillButton } from './fill.jsx';
import type { Rule } from './card.jsx';
import {
  ChipSpace, ConstraintChips, ConstraintNode, GROUP_COLLAPSE_LEAVES, Note,
  logicalHead, countLeaves, titleOf, foldValue,
} from './constraint-content.jsx';
import type { Constraint } from './constraint-content.jsx';
import './constraints.css';
import { headerControls } from '../shared/header-selection.js';

function LargeGroup(props: { c: Constraint }): JSX.Element {
  const [open, setOpen] = createSignal(false);
  const summary = () => text('constraint.foldSummary', {
    label: props.c.label || text('constraint.compound'),
    head: logicalHead(props.c.logical as string),
    n: countLeaves(props.c),
  });
  return (
    <details class="c-fold" onToggle={(e) => setOpen(e.currentTarget.open)}>
      <summary class="vl-summary muted" {...headerControls()}>
        <span>{summary()}</span>
        <Chevron small />
      </summary>
      <div class="c-fold-body">
        <Show when={open()}>
          <ConstraintNode c={{ ...props.c, label: null }} />
        </Show>
      </div>
    </details>
  );
}

export function ConstraintRow(props: {
  c: Constraint;
  scope?: string | null;
  rule?: Rule | null;
}): JSX.Element {
  const c = () => props.c;
  const assured = () => !!(c().technicalMeasure && c().conformsOp && c().conformsTo);
  const large = () => !!(c().logical && (c().children || []).length
    && countLeaves(c()) > GROUP_COLLAPSE_LEAVES);
  const nested = () => !!(c().logical && (c().children || []).length);
  const foldIri = () => (nested() ? null : foldValue(c(), coversNode));
  const spot = () => c().rowRef || c().iri || c().sentence || '';
  const actions = () => (
    <>
      <ChipSpace />
      <ChipSpace />
      <ConstraintFillButton c={c()} scope={props.scope ?? null} />
    </>
  );
  const strip = () => (
    <Hook
      name="constraintStrip"
      ctx={{ c: c(), rule: props.rule ?? null, scope: props.scope ?? null }}
    />
  );

  const nameAffordance = () => (
    <Show when={!c().iri && !assured() && (c() as { term?: unknown }).term}>
      <Field spec={{
        term: (c() as { term?: unknown }).term,
        kind: 'iri',
        preds: [],
        variant: 'nodeIri',
        iri: null,
      }}
      />
    </Show>
  );
  return (
    <li
      class={'constraint'
        + (c().purposeBinding ? ' doelbinding' : '')
        + (assured() ? ' technisch' : '')}
      title={titleOf(c())}
      data-ref={c().rowRef || c().iri || undefined}
    >
      <NodeChain.Provider value={[`vw:${props.scope || ''}|${spot()}`]}>
        <RowFold
          iri={foldIri()}
          header={(chevron) => (
            <>
              <Show when={nested()} fallback={(
                <>
                  <ConstraintChips c={c()} foldIri={foldIri()} chevron={chevron} />
                  <Note c={c()} />
                </>
              )}
              >
                <Show when={large()} fallback={<ConstraintNode c={c()} />}>
                  <LargeGroup c={c()} />
                </Show>
              </Show>
              {nameAffordance()}
              {actions()}
              {strip()}
            </>
          )}
        />
      </NodeChain.Provider>
    </li>
  );
}

export function ConstraintFillButton(props: {
  c: Constraint; scope?: string | null;
}): JSX.Element {
  const c = () => props.c;
  const assured = () => !!c().technicalMeasure;
  const target = () => {
    if (!c().iri && !assured()) return null;
    if (assured()) return c().rowRef || null;
    return (coverageNext(c()) as unknown[]).length ? c().iri || null : null;
  };
  return (
    <Show when={target()}>{(d) => (
      <FillButton target={d()} scope={props.scope ?? null} />
    )}</Show>
  );
}

export function constraintList(rule: Rule, shownDims?: string[]): Constraint[] {
  const list: Constraint[] = [
    ...((rule.constraints || []) as Constraint[]),
    ...((rule.refinements || []) as Constraint[]),
  ];
  const p = rule.purpose as (Rule['purpose'] & {
    operatorWord?: string; operatorDesc?: string;
  }) | null | undefined;
  if (!p) return list;
  if ((shownDims || []).includes(PROFILE_PATTERNS.purposeLeftOperand)
    && !editLayerActive()) return list;
  const pc = ((rule as { purposeConstraint?: Constraint }).purposeConstraint
    || {}) as Constraint;
  list.unshift({
    ...pc,
    slots: {
      left: { text: text('left.purpose'), desc: '' },
      operator: { text: p.operatorWord || text('op.eq'), desc: p.operatorDesc || '' },
      right: { texts: [p.label || ''], descs: [p.desc || ''] },
    },
    iri: pc.iri || null,
    label: pc.label || null,
    comment: pc.comment || null,
    organisational: !!pc.organisational,
    purposeBinding: true,
    unknownProps: [],
  });
  return list;
}

export function Constraints(props: {
  rule: Rule; scope?: string | null;
  shownDims?: string[];
}): JSX.Element {
  const list = createMemo(() => constraintList(props.rule, props.shownDims));
  return (
    <Show when={list().length || editLayerActive()}>
      <TermHeader tag="h4" key="head.constraints" />
      <ul class="clean constraints">
        <For each={list()}>{(c) => (
          <ConstraintRow c={c} scope={props.scope} rule={props.rule} />
        )}</For>
        <Hook
          name="constraintGhost"
          ctx={{ rule: props.rule, kind: 'permission', dims: activeDimensions() }}
        />
      </ul>
    </Show>
  );
}
