import { createEffect, createMemo, createSignal, For, Match, Show, Switch } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  MEMBER_TREE_MAX_DEPTH, groupCollectionMembers, memberSummary,
  memberTreeLevel, refListCollapsed,
} from '../../model-boundary.js';
import type { MemberGroup, MemberLevel, Member, Term } from '../../model-boundary.js';
import { endpoint, graph, graphVersion, fetchCollectionLevel } from '../../stores/corpus.js';
import { isOpen, setOpen } from '../../stores/open-state.js';
import { foldState } from '../shared/fold-state.js';
import { text } from '../../stores/view.js';
import { Chevron } from '../shared/chip.jsx';
import './members.css';
import { headerControls, selectionWithin } from '../shared/header-selection.js';

export interface OpenState {
  open(key: string): boolean;
  set(key: string, open: boolean): void;
}

const TREE_STATE: OpenState = { open: isOpen, set: setOpen };

// The full ancestor path, not the IRI alone: the same member under two parents is
// two branches.
function branchKey(path: string[], iri: string): string {
  return 'tree:' + [...path, iri].join('|');
}

export interface CollectionDesc {
  iri?: string | null;
  curie?: string | null;
  label?: string | null;
  anon?: boolean;
  term?: Term;
  members?: Member[];
  collKind?: string | null;
}

function MemberName(props: { member: Member }): JSX.Element {
  return (
    <span class="member-name" title={props.member.desc || undefined}>{props.member.label}</span>
  );
}

interface LevelOptions {
  kind: string | null;
  ancestors: string[];
  depth: number;
  state: OpenState;
}

function MemberRow(props: { member: Member; kind: string | null; options: LevelOptions }): JSX.Element {
  const key = () => branchKey(props.options.ancestors, props.member.iri);
  const open = () => props.options.state.open(key());
  const hasMembers = () => !!props.member.hasChildren && !props.member.cycle;
  const branch = () => hasMembers() && props.options.depth < MEMBER_TREE_MAX_DEPTH;
  const deeper = () => hasMembers() && props.options.depth >= MEMBER_TREE_MAX_DEPTH;
  const onClick = (e: MouseEvent): void => {
    if (!branch()) return;
    const row = e.currentTarget as HTMLElement;
    if (selectionWithin(row)) return;
    props.options.state.set(key(), !open());
  };
  return (
    <>
      <tr
        class="member-row"
        classList={{ 'member-branch': branch() }}
        data-iri={props.member.iri}
        data-ref={props.member.iri}
        title={props.member.iri}
        onClick={onClick}
      >
        <td class="member-name-cell">
          <MemberName member={props.member} />
          <Show when={props.member.cycle}>
            <span class="tree-note muted" title={text('tree.cycleTitle')}>
              {text('tree.cycle')}
            </span>
          </Show>
          <Show when={deeper()}>
            <span class="tree-note muted" title={text('tree.deeperTitle')}>
              {text('tree.deeper')}
            </span>
          </Show>
        </td>
        <td class="member-type muted">{props.kind || text('members.typeNone')}</td>
        <td class="member-chev-cell">
          <Show when={branch()}>
            <button
              type="button"
              class="member-toggle"
              data-open-key={key()}
              aria-expanded={open()}
              title={text('tree.expand')}
            ><Chevron small /></button>
          </Show>
        </td>
      </tr>
      <Show when={open()}>
        <tr class="member-sublevel">
          <td colspan="3">
            <Level
              root={props.member.iri}
              kind={props.options.kind}
              ancestors={props.options.ancestors}
              depth={props.options.depth + 1}
              state={props.options.state}
            />
          </td>
        </tr>
      </Show>
    </>
  );
}

function MemberTable(props: {
  groups: MemberGroup[]; options: LevelOptions; head?: boolean;
}): JSX.Element {
  const rows = () => props.groups.flatMap(
    (g) => g.items.map((member) => ({ member, kind: g.typed ? g.label : null })),
  );
  return (
    <Show when={rows().length}>
      <table class="member-table">
        <Show when={props.head}>
          <thead>
            <tr>
              <th scope="col">{text('members.colName')}</th>
              <th scope="col" class="member-type-col">{text('members.colType')}</th>
              <th scope="col" class="member-chev-cell" />
            </tr>
          </thead>
        </Show>
        <tbody>
          <For each={rows()}>{(r) => (
            <MemberRow member={r.member} kind={r.kind} options={props.options} />
          )}</For>
        </tbody>
      </table>
    </Show>
  );
}

function Level(props: {
  root: Term | string | null;
  kind: string | null;
  ancestors: string[];
  depth: number;
  state: OpenState;
  fixed?: Member[];
}): JSX.Element {
  const [lazyLoaded, setLazyLoaded] = createSignal(0);
  const [busy, setBusy] = createSignal(false);

  createEffect(() => {
    const w = props.root;
    if (typeof w !== 'string' || !endpoint()) return;
    setBusy(true);
    fetchCollectionLevel(w)
      .then((added) => { if (added) setLazyLoaded((n) => n + 1); })
      .finally(() => setBusy(false));
  });

  const level = createMemo<MemberLevel | null>(() => {
    if (props.fixed) {
      return {
        total: props.fixed.length,
        members: props.fixed,
        ancestry: [],
        groups: groupCollectionMembers(props.fixed, props.kind),
      };
    }
    const g = graph();
    if (!g || !props.root) return null;
    void graphVersion();
    void lazyLoaded();
    return memberTreeLevel(g, props.root, { kind: props.kind, ancestors: props.ancestors });
  });

  const path = (): string[] => {
    const w = props.root;
    return typeof w === 'string' ? [...props.ancestors, w] : props.ancestors;
  };
  const options = (): LevelOptions => ({
    kind: props.kind, ancestors: path(), depth: props.depth, state: props.state,
  });

  const state = (): 'loading' | 'empty' | 'full' => {
    const nv = level();
    if (nv && nv.total) return 'full';
    if (!nv || busy()) return 'loading';
    return 'empty';
  };

  interface Block { head?: string; sub?: boolean; groups: MemberGroup[] }
  const blocks = createMemo<Block[]>(() => {
    const nv = level();
    if (!nv || !nv.total) return [];
    const out: Block[] = [];
    for (const g of nv.ancestry) {
      out.push({
        head: `${g.label} (${g.count})`,
        groups: groupCollectionMembers(g.items, props.kind),
      });
      for (const s of g.subgroups) {
        out.push({
          head: `${s.label} (${s.items.length})`,
          sub: true,
          groups: groupCollectionMembers(s.items, props.kind),
        });
      }
    }
    if (nv.groups.some((g) => g.items.length)) out.push({ groups: nv.groups });
    return out;
  });
  const headAt = (): number => (props.depth === 1
    ? blocks().findIndex((b) => b.groups.some((g) => g.items.length))
    : -1);

  return (
    <div class="member-depth">
      <Switch>
        <Match when={state() === 'loading'}>
          <div class="member-loading muted">{text('tree.loading')}</div>
        </Match>
        <Match when={state() === 'empty'}>
          <div class="member-empty muted">{text('tree.empty')}</div>
        </Match>
        <Match when={state() === 'full'}>
          <For each={blocks()}>{(b, i) => (
            <>
              <Show when={b.head}>
                <div class={b.sub ? 'member-ancestry-sub muted' : 'member-ancestry-head muted'}
                  title={b.sub ? text('tree.ancestrySubTitle') : text('tree.ancestryTitle')}
                >{b.head}</div>
              </Show>
              <MemberTable groups={b.groups} options={options()} head={headAt() === i()} />
            </>
          )}</For>
        </Match>
      </Switch>
    </div>
  );
}

export interface MembersProps {
  desc: CollectionDesc;
}

export function Members(props: MembersProps): JSX.Element {
  const members = () => props.desc.members || [];
  const kind = () => props.desc.collKind || 'asset';
  const key = () => (props.desc.iri ? 'coll:' + props.desc.iri : '');
  const fold = foldState(key);
  const open = () => fold.manual()
    ?? (isOpen(key()) || !refListCollapsed(members().length));
  const [built, setBuilt] = createSignal(false);
  createEffect(() => { if (open()) setBuilt(true); });
  const state = TREE_STATE;

  const root = (): Term | string | null => {
    if (props.desc.anon) return props.desc.term || null;
    return props.desc.iri || null;
  };

  return (
    <details
      class="member-list"
      data-open-key={key() || undefined}
      open={open()}
      onToggle={(e) => {
        const nowOpen = (e.currentTarget as HTMLDetailsElement).open;
        fold.remember(nowOpen);
        setOpen(key(), nowOpen);
      }}
    >
      <summary class="member-sum muted" {...headerControls()}>
        <span class="member-count">{memberSummary(members(), kind())}</span>
        <Chevron small />
      </summary>
      <div class="member-tree">
        <Show when={built()}>
          <Level
            root={root()}
            kind={kind()}
            ancestors={[]}
            depth={1}
            state={state}
            fixed={root() ? undefined : members()}
          />
        </Show>
      </div>
    </details>
  );
}
