import { createSignal } from 'solid-js';
import { volatileState, setRowOpen } from '../../stores/open-state.js';

export interface FoldState {

  manual: () => boolean | null;

  remember: (open: boolean) => void;
}

export function foldState(key: () => string): FoldState {
  const [local, setLocal] = createSignal<boolean | null>(null);
  return {
    manual: () => (key() ? volatileState(key()) : local()),
    remember: (open: boolean) => {
      if (key()) setRowOpen(key(), open); else setLocal(open);
    },
  };
}
