import { createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { view } from '../../stores/view.js';
import type { Policy, Rule } from '../card/card.jsx';
import type { RuleKind } from './chip.jsx';

export interface CardHookCtx {
  pol: Policy;

  kind?: string;

  titleEdit?: unknown;

  kinds?: RuleKind[];

  placement?: 'section';
}

export interface RuleHookCtx {
  rule: Rule;
  kind: RuleKind;
  parent?: unknown;

  derived?: boolean;

  titleEdit?: unknown;

  scope?: string | null;

  dims?: { iri: string; label?: string | null; curie?: string | null }[];
}

export interface GroupHookCtx {
  pol: Policy;
  kind: RuleKind;

  dimIri: string;

  valueIri?: string | null;
  valueLabel?: string | null;
}

export interface ConstraintHookCtx {
  c: unknown;
  rule?: Rule | null;

  scope?: string | null;
}

export interface CollectionHookCtx {

  term: unknown;
}

export interface TargetHookCtx {
  rule: Rule;
  iri?: string | null;
}

/** The four category sections of the card list, in reading order. */
export const ADD_KINDS = ['offer', 'agreement', 'request', 'set'] as const;

export type AddKind = (typeof ADD_KINDS)[number];

export interface AddHookCtx { kind: AddKind }

// The read chunk may not import the edit layer; `stores/lazy-boundary.test.ts`
// guards that. Hence these slots instead of a direct import.
export interface EditHooks {

  cardHeader?: (ctx: CardHookCtx) => JSX.Element;

  cardGhost?: (ctx: CardHookCtx) => JSX.Element;


  ruleStrip?: (ctx: RuleHookCtx) => JSX.Element;

  dutyGhost?: (ctx: RuleHookCtx) => JSX.Element;

  groupGhost?: (ctx: GroupHookCtx) => JSX.Element;

  targetCross?: (ctx: TargetHookCtx) => JSX.Element;

  targetGhost?: (ctx: TargetHookCtx) => JSX.Element;

  constraintStrip?: (ctx: ConstraintHookCtx) => JSX.Element;

  constraintGhost?: (ctx: RuleHookCtx) => JSX.Element;

  collectionGhost?: (ctx: CollectionHookCtx) => JSX.Element;

  newPolicy?: (ctx: AddHookCtx) => JSX.Element;
}

export const GHOST_REVEAL_CLASS = 'ghost-reveal';

export const ghostRevealClass = (): string => (editLayerActive() ? ` ${GHOST_REVEAL_CLASS}` : '');

const [focusRequest, setFocusRequest] = createSignal('');

// `id` and not `value`: a blank node is `_:b12` in `id` and `b12` in `value`,
// and both sides of the lazy boundary must produce the same string.
export function focusAddress(x: unknown): string {
  if (!x) return '';
  if (typeof x === 'string') return x;
  const o = x as { id?: string; value?: string };
  return o.id || o.value || '';
}

export const editFocus = focusRequest;

export function requestEditFocus(address: string): void { setFocusRequest(address || ''); }

export function clearEditFocus(): void { setFocusRequest(''); }

export function clearFocusFor(address: string): void {
  if (address && focusRequest() === address) setFocusRequest('');
}

const [hooks, setHooks] = createSignal<EditHooks>({});

export { hooks };

export function attachEditHooks(next: EditHooks | null): void {
  setHooks(next || {});
}

export const editLayerActive = (): boolean =>
  view.editMode && Object.keys(hooks()).length > 0;

export function Hook<K extends keyof EditHooks>(props: {
  name: K;
  ctx: Parameters<NonNullable<EditHooks[K]>>[0];
}): JSX.Element {
  return (
    <>
      {(() => {

        if (!view.editMode) return null;
        const fn = hooks()[props.name] as ((c: unknown) => JSX.Element) | undefined;
        return fn ? fn(props.ctx) : null;
      })()}
    </>
  );
}
