import { For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { isOpen, setOpen } from '../../stores/open-state.js';
import { editLayerActive, Hook } from '../shared/edit-hook.jsx';
import { text } from '../../stores/view.js';
import { Chevron } from '../shared/chip.jsx';
import { Kv, TermHeader } from '../shared/header.jsx';
import { headerControls } from '../shared/header-selection.js';
import { Members } from './members.jsx';
import type { CollectionDesc } from './members.jsx';
import { ChipSpace, ConstraintChips } from './constraint-content.jsx';
import type { Constraint } from './constraint-content.jsx';
import { ConstraintFillButton } from './constraints.jsx';
import './collection.css';

export interface Intension {
  kind?: string | null;
  refinements?: Constraint[];
  phrase?: string | null;
  source?: { iri?: string | null; curie?: string | null; label?: string | null } | null;
}

export interface CollectionNode extends CollectionDesc {
  intension?: Intension | null;
}

export function isCollection(d: CollectionNode | null | undefined): boolean {
  return !!d && (!!d.intension || !!(d.members || []).length || !!d.collKind);
}

function showsMembers(d: CollectionNode): boolean {
  return !!d.collKind || !!(d.members || []).length;
}

export function KindChip(props: { kind?: string | null }): JSX.Element {
  return (
    <span class="kind-pill coll">
      {text(props.kind === 'party' ? 'coll.kindParty' : 'coll.kindAsset')}
    </span>
  );
}

function SourceValue(props: { src: NonNullable<Intension['source']>; kind?: string | null }): JSX.Element {
  return (
    <span class="coll-source-line">
      <KindChip kind={props.kind} />
      <ChipSpace />
      <span class="coll-source-name">{props.src.label || props.src.curie || ''}</span>
    </span>
  );
}

function RefinementSection(props: { ix: Intension | null; term: unknown }): JSX.Element {
  const refs = () => (props.ix && props.ix.refinements) || [];
  return (
    <>
      <Show when={!refs().length && props.ix && props.ix.phrase}>
        <span class="coll-phrase">{props.ix!.phrase}</span>
      </Show>
      <Show when={refs().length || editLayerActive()}>
      <TermHeader tag="h4" key="coll.refinementSection" />
      <ul class="clean coll-refinements">
        <For each={refs()}>{(r) => (
          <li class="coll-refinement" title={[r.label, r.comment].filter(Boolean).join(' — ') || undefined}>
            <ConstraintChips c={r} />
            <Show when={r.label}>{(l) => (
              <><ChipSpace /><span class="c-note muted">{l()}</span></>
            )}</Show>
            <ChipSpace />
            <ChipSpace />
            <ConstraintFillButton c={r} />
            <Hook name="constraintStrip" ctx={{ c: r, rule: null }} />
          </li>
        )}</For>
        <Hook name="collectionGhost" ctx={{ term: props.term }} />
      </ul>
      </Show>
    </>
  );
}

function CollectionBody(props: {
  desc: CollectionNode; ix: Intension | null; extra?: string;
}): JSX.Element {
  const kind = () => props.desc.collKind || (props.ix && props.ix.kind) || 'asset';
  const term = () => props.desc.term ?? props.desc.iri ?? null;
  const showMembers = () => (props.ix
    ? (props.desc.members || []).length > 0 : showsMembers(props.desc));
  return (
    <div class={'coll-body' + (props.extra ? ' ' + props.extra : '')}>
      <Show when={props.ix && props.ix.source}>{(src) => (
        <Kv rows={[{
          key: 'field.source',
          value: <SourceValue src={src()} kind={kind()} />,
          ref: src().iri,
        }]}
        />
      )}</Show>
      <RefinementSection ix={props.ix} term={term()} />
      <Show when={showMembers()}><Members desc={props.desc} /></Show>
    </div>
  );
}

export function Collection(props: {
  desc: CollectionNode;
  tag: (iri: string | null) => JSX.Element;
}): JSX.Element {
  const ix = () => props.desc.intension || null;
  const kind = () => props.desc.collKind || (ix() && ix()!.kind) || 'asset';
  const key = () => (props.desc.iri ? 'colldef:' + props.desc.iri : undefined);
  const open = () => (key() ? isOpen(key()!) : false);
  const showBody = () => ix() || (editLayerActive() && props.desc.collKind === 'party');
  return (
    <Show
      when={showBody()}
      fallback={(
        <>
          {props.tag(props.desc.anon ? null : props.desc.iri || null)}
          <Show when={showsMembers(props.desc)}><Members desc={props.desc} /></Show>
        </>
      )}
    >
      <Show
        when={!props.desc.anon}
        fallback={(
          <>
            <KindChip kind={kind()} />
            <ChipSpace />
            <CollectionBody desc={props.desc} ix={ix()} />
          </>
        )}
      >
        <details
          class="coll-fold"
          data-open-key={key()}
          open={open() || (editLayerActive() && !ix())}
          onToggle={(e) => { if (key()) setOpen(key()!, e.currentTarget.open); }}
        >
          <summary class="vl-summary coll-summary" {...headerControls()}>
            <KindChip kind={kind()} />
            <ChipSpace />
            {props.tag(props.desc.iri || null)}
            <Chevron />
          </summary>
          <CollectionBody desc={props.desc} ix={ix()} extra="coll-fold-body" />
        </details>
      </Show>
    </Show>
  );
}
