import { createEffect, createMemo, createSignal, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  CARD_CHUNK_SIZE, REF_LIST_INLINE_MAX, filterRefItems, incomingRefCount, incomingRefs,
  refListCollapsed,
} from '../../model-boundary.js';
import type { Term, Reference } from '../../model-boundary.js';
import { graph, graphVersion } from '../../stores/corpus.js';
import { isOpen, setOpen } from '../../stores/open-state.js';
import { foldState } from '../shared/fold-state.js';
import { text } from '../../stores/view.js';
import { Chevron } from '../shared/chip.jsx';
import { predicateText, refRowText } from './reference-text.js';
import './back-references.css';
import { headerControls } from '../shared/header-selection.js';

interface RowItem { title: string; sub: string; ref: Reference }

function ReferrerRow(props: { item: RowItem }): JSX.Element {
  const ref = () => props.item.ref;
  return (
    <li class={ref().iri ? 'usedby-ref' : 'usedby-ref usedby-anon'} title={ref().iri || undefined}>
      <span class="usedby-name" title={ref().desc || undefined}>{props.item.title}</span>
      <Show when={props.item.sub}>
        <span class="usedby-pred mono muted" title={ref().predicate?.desc || undefined}>
          {props.item.sub}
        </span>
      </Show>
    </li>
  );
}

export interface BackReferencesProps {
  iri?: string | null;
  term?: Term;
}

export function BackReferences(props: BackReferencesProps): JSX.Element {
  const [built, setBuilt] = createSignal(false);
  const [filter, setFilter] = createSignal('');
  const [limit, setLimit] = createSignal(CARD_CHUNK_SIZE);

  const node = () => props.term || props.iri || null;
  const count = createMemo(() => {
    const g = graph();
    const k = node();
    if (!g || !k) return 0;
    void graphVersion();
    return incomingRefCount(g, k);
  });

  const key = () => (props.iri ? 'usedby:' + props.iri : '');
  const fold = foldState(key);
  const open = () => fold.manual()
    ?? (isOpen(key()) || !refListCollapsed(count()));

  // A <details> that renders already open never fires toggle, so build on open().
  createEffect(() => { if (open()) setBuilt(true); });

  // The count is a cheap index descent; incomingRefs builds a label per referrer,
  // so the list waits for the block to open.
  const items = createMemo<RowItem[]>(() => {
    const g = graph();
    const k = node();
    if (!built() || !g || !k) return [];
    void graphVersion();
    return incomingRefs(g, k).map((r) => {
      const txt = refRowText(r);
      return { title: txt.title, sub: txt.pred || predicateText(r.predicate), ref: r };
    });
  });
  const visible = createMemo(() => filterRefItems(items(), filter()));
  const shown = createMemo(() => visible().slice(0, limit()));
  const rest = () => visible().length - shown().length;

  return (
    <Show when={count()}>
      <details
        class="usedby"
        data-open-key={key() || undefined}
        open={open()}
        onToggle={(e) => {
          const nowOpen = (e.currentTarget as HTMLDetailsElement).open;
          fold.remember(nowOpen);
          setOpen(key(), nowOpen);
        }}
      >
        <summary class="usedby-sum muted" title={text('usedBy.title')} {...headerControls()}>
          <span class="usedby-count">{text('usedBy.count', { n: count() })}</span>
          <Chevron small />
        </summary>
        <Show when={built()}>
          <Show when={items().length > REF_LIST_INLINE_MAX}>
            <input
              type="search"
              class="usedby-filter"
              placeholder={text('usedBy.filterPlaceholder')}
              aria-label={text('usedBy.filterAria')}
              value={filter()}
              onInput={(e) => { setFilter(e.currentTarget.value); setLimit(CARD_CHUNK_SIZE); }}
            />
          </Show>
          <ul class="usedby-list">
            <For each={shown()}>{(item) => <ReferrerRow item={item} />}</For>
          </ul>
          <button
            type="button"
            class="btn usedby-more"
            hidden={rest() <= 0}
            onClick={() => setLimit((n) => n + CARD_CHUNK_SIZE)}
          >{text('list.showMoreRest', { n: rest() })}</button>
        </Show>
      </details>
    </Show>
  );
}
